import java.util.*;
import java.io.*;
public class Main {
  public static void main(String[] args) throws IOException {
    String[] t = new String(System.in.readAllBytes()).trim().split("\\s+");
    int p = 0;
    int n = Integer.parseInt(t[p++]), k = Integer.parseInt(t[p++]); int[] a = new int[n];
    for (int i = 0; i < n; i++) a[i] = Integer.parseInt(t[p++]);
    System.out.println(count(a, 0, k));
  }
  static long count(int[] a, int i, int rem) {
    if (rem == 0) return 1;
    if (i == a.length || rem < 0) return 0;
    return count(a, i + 1, rem - a[i]) + count(a, i + 1, rem);
  }
}

